        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/2332",
      ),
      Ayah(
        numberInSurah: 83,
        numberInQuran: 2333,
        juz: 16,
        page: 311,
        arab: "\u0623\u064e\u0644\u064e\u0645\u0652 \u062a\u064e\u0631\u064e \u0623\u064e\u0646\u0651\u064e\u0627 \u0623\u064e\u0631\u0652\u0633\u064e\u0644\u0652\u0646\u064e\u0627 \u0627\u0644\u0634\u0651\u064e\u064a\u064e\u0627\u0637\u0650\u064a\u0646\u064e \u0639\u064e\u0644\u064e\u0649 \u0627\u0644\u0652\u0643\u064e\u0627\u0641\u0650\u0631\u0650\u064a\u0646\u064e \u062a\u064e\u0624\u064f\u0632\u0651\u064f\u0647\u064f\u0645\u0652 \u0623\u064e\u0632\u0651\u064b\u0627",
        transliteration: "Alam tara annaaa arsalnash Shayaateena 'alal kaafireena ta'uzzuhum azzaa",
        translation: "Tidakkah engkau melihat, bahwa sesungguhnya Kami telah mengutus setan-setan itu kepada orang-orang kafir untuk mendorong mereka (berbuat maksiat) dengan sungguh-sungguh?",
        shortTafsir: "Wahai Nabi Muhammad,\u00a0tidakkah engkau melihat bahwa sesungguhnya Kami telah mengutus setan-setan itu kepada orang-orang kafir\u00a0yang selalu ingkar dan engggan bertobat\u00a0untuk mendorong mereka\u00a0berbuat maksiat\u00a0dengan sungguh-sungguh\u00a0sehingga mereka semakin terperosok dalam kesesatannya?",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/2333",
      ),
      Ayah(
        numberInSurah: 84,
        numberInQuran: 2334,
        juz: 16,
        page: 311,
        arab: "\u0641\u064e\u0644\u064e\u0627 \u062a\u064e\u0639\u0652\u062c\u064e\u0644\u0652 \u0639\u064e\u0644\u064e\u064a\u0652\u0647\u0650\u0645\u0652 \u06d6 \u0625\u0650\u0646\u0651\u064e\u0645\u064e\u0627 \u0646\u064e\u0639\u064f\u062f\u0651\u064f \u0644\u064e\u0647\u064f\u0645\u0652 \u0639\u064e\u062f\u0651\u064b\u0627",
        transliteration: "Falaa ta'jal alaihim innamaa na 'uddu lahum 'addaa",
        translation: "Maka janganlah engkau (Muhammad) tergesa-gesa (memintakan azab) terhadap mereka, karena Kami menghitung dengan hitungan teliti (datangnya hari siksaan) untuk mereka.",
        shortTafsir: "Wahai Nabi, apa yang terjadi merupakan ketetapan Allah,\u00a0maka janganlah engkau\u00a0gelisah dengan sikap mereka sehingga engkau\u00a0tergesa-gesa\u00a0meminta jatuhnya azab\u00a0terhadap mereka, karena\u00a0sesungguhnya Kami membiarkan mereka dalam keadaan ini sampai waktu tertentu. Kami lakukan hal itu agar\u00a0Kami\u00a0terus\u00a0menghitung\u00a0dosa-dosa dan penyimpangan mereka\u00a0dengan hitungan teliti\u00a0sampai datangnya hari siksaan diakhirat\u00a0untuk mereka.",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/2334",
      ),
      Ayah(
