        arab: "\u0648\u064e\u0645\u064e\u0627 \u064a\u064e\u0646\u0628\u064e\u063a\u0650\u064a \u0644\u0650\u0644\u0631\u0651\u064e\u062d\u0652\u0645\u064e\u0670\u0646\u0650 \u0623\u064e\u0646 \u064a\u064e\u062a\u0651\u064e\u062e\u0650\u0630\u064e \u0648\u064e\u0644\u064e\u062f\u064b\u0627",
        transliteration: "Wa maa yambaghee lir Rahmaani ai yattakhiza waladaa",
        translation: "Dan tidak mungkin bagi (Allah) Yang Maha Pengasih mempunyai anak.",
        shortTafsir: "Dan\u00a0sungguh,\u00a0tidak mungkin bagi\u00a0Allah\u00a0Yang Maha Pengasih mempunyai\u00a0atau mengangkat\u00a0anak.\u00a0Allah Yang Mahakaya tidak membutuhkan apa pun. Jika Dia mempunyai anak, pasti anak itu serupa dengan-Nya, dan hal ini akan menghilangkan esensi keesaan-Nya.",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/2342",
      ),
      Ayah(
        numberInSurah: 93,
        numberInQuran: 2343,
        juz: 16,
        page: 311,
        arab: "\u0625\u0650\u0646 \u0643\u064f\u0644\u0651\u064f \u0645\u064e\u0646 \u0641\u0650\u064a \u0627\u0644\u0633\u0651\u064e\u0645\u064e\u0627\u0648\u064e\u0627\u062a\u0650 \u0648\u064e\u0627\u0644\u0652\u0623\u064e\u0631\u0652\u0636\u0650 \u0625\u0650\u0644\u0651\u064e\u0627 \u0622\u062a\u0650\u064a \u0627\u0644\u0631\u0651\u064e\u062d\u0652\u0645\u064e\u0670\u0646\u0650 \u0639\u064e\u0628\u0652\u062f\u064b\u0627",
        transliteration: "In kullu man fis samaawaati wal ardi illaaa aatir Rahmaani 'abdaa",
        translation: "Tidak ada seorang pun di langit dan di bumi, melainkan akan datang kepada (Allah) Yang Maha Pengasih sebagai seorang hamba.",
        shortTafsir: "Untuk menguatkan tidak adanya anak bagi-Nya, Allah menyatakan bahwa\u00a0tidak ada seorang pun di langit dan di bumi, yaitu di alam semesta ini,\u00a0melainkan\u00a0kelak di hari kiamat\u00a0akan datang\u00a0dan menghadap\u00a0kepada\u00a0Allah\u00a0Yang Maha Pengasih sebagai seorang hamba. Mereka datang dengan tunduk dan patuh.",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/2343",
      ),
      Ayah(
        numberInSurah: 94,
        numberInQuran: 2344,
        juz: 16,
        page: 311,
        arab: "\u0644\u0651\u064e\u0642\u064e\u062f\u0652 \u0623\u064e\u062d\u0652\u0635\u064e\u0627\u0647\u064f\u0645\u0652 \u0648\u064e\u0639\u064e\u062f\u0651\u064e\u0647\u064f\u0645\u0652 \u0639\u064e\u062f\u0651\u064b\u0627",
        transliteration: "Laqad ahsaahum wa addahum 'addaa",
        translation: "Dia (Allah) benar-benar telah menentukan jumlah mereka dan menghitung mereka dengan hitungan yang teliti.",
        shortTafsir: "Semua manusia akan kembali pada Allah dan\u00a0Dia benar-benar telah mengetahui mereka dengan rinci, bagaimana kepribadian, kejiwaan, perbuatan, dan perkataan mereka secara lahir maupun batin. Dia juga akan memeriksa\u00a0dan menghitung mereka dengan hitungan yang teliti\u00a0sehingga tidak ada satu pun yang terlewat.",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/2344",
      ),
      Ayah(
        numberInSurah: 95,
        numberInQuran: 2345,
        juz: 16,
        page: 311,
        arab: "\u0648\u064e\u0643\u064f\u0644\u0651\u064f\u0647\u064f\u0645\u0652 \u0622\u062a\u0650\u064a\u0647\u0650 \u064a\u064e\u0648\u0652\u0645\u064e \u0627\u0644\u0652\u0642\u0650\u064a\u064e\u0627\u0645\u064e\u0629\u0650 \u0641\u064e\u0631\u0652\u062f\u064b\u0627",
        transliteration: "Wa kulluhum aateehi Yawmal Qiyaamati fardaa",
        translation: "Dan setiap orang dari mereka akan datang kepada Allah sendiri-sendiri pada hari Kiamat.",
        shortTafsir: "Dan setiap orang dari mereka akan datang dan menghadap kepada Allah untuk menerima perhitungan dan putusan tentang perbuatannya di dunia secara sendiri-sendiri kelak pada hari kiamat. Tidak ada teman yang membantu dan tidak ada pula orang tua atau anak yang menolong.",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/2345",
      ),
      Ayah(
        numberInSurah: 96,
        numberInQuran: 2346,
        juz: 16,
        page: 312,
        arab: "\u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0622\u0645\u064e\u0646\u064f\u0648\u0627 \u0648\u064e\u0639\u064e\u0645\u0650\u0644\u064f\u0648\u0627 \u0627\u0644\u0635\u0651\u064e\u0627\u0644\u0650\u062d\u064e\u0627\u062a\u0650 \u0633\u064e\u064a\u064e\u062c\u0652\u0639\u064e\u0644\u064f \u0644\u064e\u0647\u064f\u0645\u064f \u0627\u0644\u0631\u0651\u064e\u062d\u0652\u0645\u064e\u0670\u0646\u064f \u0648\u064f\u062f\u0651\u064b\u0627",
        transliteration: "Innal lazeena aamanoo wa 'amilus saalihaati sa yaj'alu lahumur Rahmaanu wuddaa",
        translation: "Sungguh, orang-orang yang beriman dan mengerjakan kebajikan, kelak (Allah) Yang Maha Pengasih akan menanamkan rasa kasih sayang (dalam hati mereka).",
        shortTafsir: "Usai menegasikan keyakinan orang musyrik bahwa Allah mempunyai anak dan perhitungan yang akan mereka peroleh, Dia lalu beralih menerangkan balasan bagi orang mukmin dan beramal saleh.\u00a0Sungguh, orang-orang yang beriman\u00a0dengan teguh\u00a0dan\u00a0membuktikan keimanannya dengan\u00a0mengerjakan kebajikan, kelak\u00a0Allah\u00a0Yang Maha Pengasih akan menanamkan rasa kasih sayang\u00a0dalam dirinya kepada sesama orang beriman.",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/2346",
      ),
      Ayah(
        numberInSurah: 97,
        numberInQuran: 2347,
        juz: 16,
        page: 312,
        arab: "\u0641\u064e\u0625\u0650\u0646\u0651\u064e\u0645\u064e\u0627 \u064a\u064e\u0633\u0651\u064e\u0631\u0652\u0646\u064e\u0627\u0647\u064f \u0628\u0650\u0644\u0650\u0633\u064e\u0627\u0646\u0650\u0643\u064e \u0644\u0650\u062a\u064f\u0628\u064e\u0634\u0651\u0650\u0631\u064e \u0628\u0650\u0647\u0650 \u0627\u0644\u0652\u0645\u064f\u062a\u0651\u064e\u0642\u0650\u064a\u0646\u064e \u0648\u064e\u062a\u064f\u0646\u0630\u0650\u0631\u064e \u0628\u0650\u0647\u0650 \u0642\u064e\u0648\u0652\u0645\u064b\u0627 \u0644\u0651\u064f\u062f\u0651\u064b\u0627",
        transliteration: "Fa innamaa yassarnaahu bilisaanika litubashshira bihil muttaqeena wa tunzira bihee qawmal luddaa",
        translation: "Maka sungguh, telah Kami mudahkan (Al-Qur'an) itu dengan bahasamu (Muhammad), agar dengan itu engkau dapat memberi kabar gembira kepada orang-orang yang bertakwa, dan agar engkau dapat memberi peringatan kepada kaum yang membangkang.",
        shortTafsir: "Wahai Nabi, maka sampaikanlah janji Allah kepada umatmu bahwa sesungguhnya telah Kami mudahkan Al-Qur\u2019an itu dengan bahasamu. Yang demikian ini agar dengan itu engkau dapat memberi kabar gembira tentang janji dan rahmat Allah kepada orang-orang yang bertakwa yang selalu melaksanakan perintah-Nya dan menjauhi larangan-Nya, dan agar engkau dapat memberi peringatan tentang murka dan hukuman-Nya kepada kaum yang membangkang dan mengingkari ajaran-Nya.",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/2347",
      ),
      Ayah(
        numberInSurah: 98,
        numberInQuran: 2348,
        juz: 16,
        page: 312,
        arab: "\u0648\u064e\u0643\u064e\u0645\u0652 \u0623\u064e\u0647\u0652\u0644\u064e\u0643\u0652\u0646\u064e\u0627 \u0642\u064e\u0628\u0652\u0644\u064e\u0647\u064f\u0645 \u0645\u0651\u0650\u0646 \u0642\u064e\u0631\u0652\u0646\u064d \u0647\u064e\u0644\u0652 \u062a\u064f\u062d\u0650\u0633\u0651\u064f \u0645\u0650\u0646\u0652\u0647\u064f\u0645 \u0645\u0651\u0650\u0646\u0652 \u0623\u064e\u062d\u064e\u062f\u064d \u0623\u064e\u0648\u0652 \u062a\u064e\u0633\u0652\u0645\u064e\u0639\u064f \u0644\u064e\u0647\u064f\u0645\u0652 \u0631\u0650\u0643\u0652\u0632\u064b\u0627",
        transliteration: "Wa kam ahlaknaa qabla hum min qarnin hal tuhissu minhum min ahadin aw tasma'u lahum rikzaa",
        translation: "Dan berapa banyak umat yang telah Kami binasakan sebelum mereka. Adakah engkau (Muhammad) melihat salah seorang dari mereka atau engkau mendengar bisikan mereka?",
        shortTafsir: "Wahai Nabi, sebagai peringatan\u00a0dan\u00a0pelajaran bagi para pembangkang itu, kabarkan kepada mereka\u00a0berapa banyak umat yang telah Kami binasakan sebelum mereka\u00a0akibat keingkaran dan kedurhakaan mereka. Kami hancurkan mereka, lalu\u00a0adakah engkau melihat salah seorang dari mereka atau engkau mendengar bisikan mereka? Tidak! Maka, sebagaimana Kami binasakan umat terdahulu itu, Kami pasti akan membinasakan kaummu yang ingkar.",
        sajda: false,
        audioUrl: "https://cdn.alquran.cloud/media/audio/ayah/ar.alafasy/2348",
      ),
    ],
  );
}
